const agente = $('Agente JULIETA').item.json.output;
const datos = $('Datos1').last().json;
const filaAnterior = $('AñadirColumna').last().json;

const mensajeCliente = datos.Mensaje || null;

function normalizarPresupuesto(valor) {
  if (!valor) return null;
  const numeros = valor.match(/\d[\d.,]*/g);
  if (!numeros || numeros.length === 0) return null;
  const limpiar = (n) => parseFloat(n.replace(/,/g, ""));
  const valores = numeros.map(limpiar).filter((n) => !isNaN(n));
  if (valores.length === 0) return null;
  if (valores.length === 1) return Math.round(valores[0]);
  return Math.round((valores[0] + valores[1]) / 2);
}

// Si el agente deja un dato vacío, se conserva el que ya estaba guardado
// --- Historial: registra la interacción de ESTE turno (cliente + agente) ---
let historial = [];
try {
  historial = Array.isArray(filaAnterior.historial_conversacion)
    ? filaAnterior.historial_conversacion
    : JSON.parse(filaAnterior.historial_conversacion || "[]");
} catch (e) {
  historial = [];
}

historial.push({
  cliente: mensajeCliente,
  agente: agente.mensaje_para_cliente
});

historial = historial.slice(-3);

const update = {
  nombre: agente.nombre || filaAnterior.nombre || datos.Nombre || null,
  destino: agente.destino || filaAnterior.destino || null,
  fecha: agente.fecha || filaAnterior.fecha_salida || null,
  fecha_regreso: agente.fecha_regreso || filaAnterior.fecha_regreso || null,
  Adultos: agente.adultos ? parseInt(agente.adultos, 10) : (filaAnterior.Adultos ?? null),
  Niños: agente.ninos !== "" && agente.ninos != null ? parseInt(agente.ninos, 10) : (filaAnterior['Niños'] ?? null),
  Edad_ninios: agente.edad_ninios || filaAnterior.Edad_ninios || null,
  fechas_texto: agente.fechas_texto || filaAnterior.fechas_texto || null,
  notas_ia: agente.notas || filaAnterior.notas_ia || null,
  completo: agente.todos_los_datos_completos === true,
  es_duda: agente.es_duda === true,
  pregunta_duda: agente.pregunta_duda || null,
  campo_decision: agente.campo_decision || null,
  pregunta_anterior: agente.mensaje_para_cliente || null,
  respuesta_anterior: mensajeCliente,
  historial_conversacion: JSON.stringify(historial),
  ult_mensaje: new Date().toISOString()
};


// ===== Red de seguridad (no depender solo del modelo) =====
const PERSONA = 'Julieta de RsViajes Matriz';
const esPrimer = !filaAnterior.contact_id;
const textoCliente = String(mensajeCliente || '');
// 1) No aceptar fechas exactas nuevas si el cliente no mencionó una fecha en este mensaje
const mencionaFecha = /\d{1,2}\s*(de|al|a|\/|-)\s*\d{0,2}|enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre|hoy|mañana|semana|puente|noche|d[ií]as?\b|fin de/i.test(textoCliente);
if (!filaAnterior.fecha_salida && update.fecha && !mencionaFecha) { update.fecha = filaAnterior.fecha_salida || null; update.fecha_regreso = filaAnterior.fecha_regreso || null; }
// 2) Qué datos están resueltos (un "no sé" anotado cuenta como resuelto)
const notas = String(update.notas_ia || '').toLowerCase();
const num = (v) => v !== null && v !== undefined && v !== '' && !isNaN(v);
const r = {
  destino: !!update.destino,
  fechas: !!((update.fecha && update.fecha_regreso) || update.fechas_texto),
  adultos: num(update.Adultos) || /adult/.test(notas),
  ninos: num(update['Niños']) || /(niñ|menor)/.test(notas),
};
r.edades = !(Number(update['Niños']) > 0) || !!update.Edad_ninios || /edad/.test(notas);
const completoCalc = Object.values(r).every(Boolean);
const PREGUNTAS = {
  destino: '¿A qué destino te gustaría viajar? 🏖️',
  fechas: '¿Qué fechas tienes en mente para tu viaje? Si aún no lo sabes, no hay problema 😊',
  adultos: '¿Cuántos adultos viajarán?',
  ninos: '¿Viajan niños? Si es así, ¿cuántos?',
  edades: '¿Qué edades tienen los niños?',
};
const pendiente = Object.keys(r).find(k => !r[k]);
let mensaje = String(agente.mensaje_para_cliente || '');
// 3) Texto roto (caracteres de control) → no se envía así
const roto = /[\u0000-\u0008\u000B\u000C\u000E-\u001F]/.test(mensaje);
// 4) Pregunta por fechas cuando ya están resueltas → se cambia por el siguiente dato pendiente
const preguntaFechas = r.fechas && /\?/.test(mensaje) && /(fecha|noches|cu[aá]ndo|regres|salir|salida)/i.test(mensaje.split(/[.!]\s/).pop());
if (completoCalc && !agente.todos_los_datos_completos) {
  mensaje = '¡Perfecto! Con esto ya tengo lo necesario para preparar tu cotización 😊';
} else if (roto || preguntaFechas || !mensaje.trim()) {
  const saludo = esPrimer ? `¡Hola! Soy ${PERSONA} 😊 ` : (preguntaFechas ? '¡Gracias! ' : '');
  mensaje = saludo + (pendiente ? PREGUNTAS[pendiente] : '¡Perfecto! Ya tengo lo necesario para preparar tu cotización 😊');
}
update.completo = agente.todos_los_datos_completos === true || completoCalc;
update.pregunta_anterior = mensaje;
if (historial.length) historial[historial.length - 1].agente = mensaje;
update.historial_conversacion = JSON.stringify(historial);

return [{ json: update }];

