const fechaStr = $('Parser de datos1').first().json.fecha;

// Parseamos la fecha asumiendo formato DD/MM/YYYY (como "12/08/2026")
// Si en algún caso llega en otro formato, ajusta el split de abajo
function parsearFecha(str) {
  if (!str) return null;

  // Intenta DD/MM/YYYY
  const partes = str.split('/');
  if (partes.length === 3) {
    const [dia, mes, anio] = partes.map(p => parseInt(p, 10));
    if (!isNaN(dia) && !isNaN(mes) && !isNaN(anio)) {
      return new Date(anio, mes - 1, dia);
    }
  }

  // Fallback: intenta que JS lo parsee directo (ISO, etc.)
  const fallback = new Date(str);
  return isNaN(fallback.getTime()) ? null : fallback;
}

const fechaViaje = parsearFecha(fechaStr);
const hoy = new Date();
hoy.setHours(0, 0, 0, 0); // normaliza para comparar solo días completos

let urgente = false;
let diasFaltantes = null;

if (fechaViaje) {
  fechaViaje.setHours(0, 0, 0, 0);
  const diffMs = fechaViaje.getTime() - hoy.getTime();
  diasFaltantes = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
  urgente = diasFaltantes >= 0 && diasFaltantes < 15;
}

return [{
  json: {
    ...items[0].json,
    Urgente: urgente,
    diasFaltantes
  }
}];

